<script setup>
import { computed, onMounted, ref } from 'vue'
import { apiGet, apiRequest } from '../services/api.js'
import { useAuthStore } from '../stores/auth.js'
import { label } from '../utils.js'
import FormPanel from '../components/FormPanel.vue'
const auth = useAuthStore(), beneficiaries = ref([]), appointments = ref([]), slots = ref([]), patient = ref(''), mode = ref('in_person'), near = ref('industry'), sort = ref('earliest'), myTeam = ref(false), latitude = ref(null), longitude = ref(null), authorized = ref(false), error = ref(''), notice = ref(''), busy = ref(false), searched = ref(false), email = ref(''), invitation = ref(''), links = ref({})
const current = computed(() => beneficiaries.value.find(b => Number(b.id) === Number(patient.value)))
const professionalRole = ref('doctor')
const supportId = ref(null)
const supportFields = [{ name: 'barrier', label: 'Dificuldade que deseja informar (opcional)', options: [{ value: 'declined', label: 'Prefiro não informar' }, { value: 'schedule', label: 'Horário / rotina' }, { value: 'transport', label: 'Transporte' }, { value: 'contact', label: 'Contato' }, { value: 'personal', label: 'Questão pessoal' }], default: 'declined' }, { name: 'administrative_note', label: 'Como podemos ajudar a organizar seu retorno?', type: 'textarea', optional: true, max: 1000, wide: true, help: 'Não inclua diagnósticos ou resultados de exames neste pedido administrativo.' }]
async function support(data) { busy.value = true; error.value = ''; try { await apiRequest(`/me/appointments/${supportId.value}/support`, 'POST', data); supportId.value = null; notice.value = 'Pedido recebido. Sua equipe APS foi avisada para organizar o acolhimento.' } catch (e) { error.value = e.message } finally { busy.value = false } }
async function load() { beneficiaries.value = await apiGet('/me/beneficiaries'); appointments.value = await apiGet('/me/appointments'); if (!patient.value) patient.value = beneficiaries.value[0]?.id || '' }
async function search() {
  busy.value = true; error.value = ''; slots.value = []; searched.value = true
  try {
    const query = { patient_id: patient.value, modality: mode.value, near: near.value, sort: sort.value, professional_role: professionalRole.value, my_team: myTeam.value ? '1' : '0' }
    if (near.value === 'home' && latitude.value !== null && longitude.value !== null) { query.latitude = latitude.value; query.longitude = longitude.value }
    slots.value = await apiGet('/availability?' + new URLSearchParams(query))
  } catch (e) { error.value = e.message } finally { busy.value = false }
}
function locate() {
  if (!navigator.geolocation) { error.value = 'Localização não disponível neste navegador. Use a unidade industrial ou ordene pelo primeiro horário.'; return }
  navigator.geolocation.getCurrentPosition(position => { latitude.value = position.coords.latitude; longitude.value = position.coords.longitude; notice.value = 'Localização obtida somente para esta busca. Selecione “Perto de mim” e aplique o filtro.' }, () => { error.value = 'Não foi possível obter a localização. Você pode buscar pela unidade industrial ou pelo primeiro horário.' }, { enableHighAccuracy: false, timeout: 10000, maximumAge: 60000 })
}
async function book(slot) {
  if (!authorized.value) { error.value = 'Confirme a autorização de vínculo com a equipe antes de agendar.'; return }
  busy.value = true; error.value = ''; notice.value = ''
  try { await apiRequest(`/availability/${slot.id}/book`, 'POST', { patient_id: Number(patient.value), version: Number(slot.version), authorize_team: authorized.value }); await load(); await search(); notice.value = 'Atendimento confirmado. A equipe escolhida foi vinculada para o acompanhamento.' }
  catch (e) { error.value = e.message; slots.value = [] } finally { busy.value = false }
}
async function confirm(a) { busy.value = true; error.value = ''; try { await apiRequest(`/me/appointments/${a.id}/confirm`, 'POST'); await load(); notice.value = 'Retorno confirmado.' } catch (e) { error.value = e.message } finally { busy.value = false } }
async function access(a) { error.value = ''; try { links.value[a.id] = (await apiGet(`/appointments/${a.id}/access`)).meeting_url } catch (e) { error.value = e.message } }
async function inviteDependent() {
  busy.value = true; error.value = ''; invitation.value = ''
  try { const result = await apiRequest(`/me/beneficiaries/${patient.value}/dependent-invitations`, 'POST', { email: email.value }); invitation.value = new URL(result.registration_path, window.location.origin).href }
  catch (e) { error.value = e.message } finally { busy.value = false }
}
onMounted(async () => { busy.value = true; try { await load() } catch (e) { error.value = e.message } finally { busy.value = false } })
</script>
<template><p class="eyebrow">ACESSO À APS · INDÚSTRIA E FAMÍLIA</p><h1>Encontre seu próximo atendimento</h1><p class="lead">Perto de casa, perto da indústria ou por teleconsulta. Escolha um horário que caiba na sua rotina, entre as disponibilidades dos próximos 90 dias.</p><p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success" role="status">{{ notice }}</p><p v-if="busy" role="status">Consultando…</p><p v-if="!busy && !beneficiaries.length" class="alert alert-info">Seu cadastro ainda não possui vínculo contratual. Procure a gestão responsável pelo convite.</p><form v-if="beneficiaries.length" class="card card-body mb-4" @submit.prevent="search"><div class="row g-3"><div class="col-md-6"><label for="beneficiary" class="form-label">Atendimento para</label><select id="beneficiary" v-model="patient" class="form-select" @change="slots = []; searched = false; authorized = false; invitation = ''"><option v-for="b in beneficiaries" :key="b.id" :value="b.id">{{ b.name }} · {{ b.kind === 'worker' ? 'Trabalhador' : 'Dependente' }} · {{ label(b.status) }}</option></select></div><div class="col-md-6"><label for="mode" class="form-label">Modalidade</label><select id="mode" v-model="mode" class="form-select" @change="slots = []; searched = false; sort = 'earliest'"><option value="in_person">Presencial</option><option value="telehealth">Teleconsulta</option></select></div><div class="col-md-6"><label for="professional-role" class="form-label">Profissional</label><select id="professional-role" v-model="professionalRole" class="form-select"><option value="doctor">Médico</option><option value="nurse">Enfermeiro</option><option value="all">Todos os profissionais</option></select></div><div class="col-md-6"><label for="near" class="form-label">Referência de localização</label><select id="near" v-model="near" class="form-select"><option value="industry">Perto da minha unidade industrial</option><option value="home">Perto de mim / de casa</option></select><button v-if="near === 'home'" type="button" class="btn btn-sm btn-outline-secondary mt-2" @click="locate">Usar minha localização nesta busca</button><small class="d-block text-secondary mt-1">Sem rastreamento contínuo. A distância é aproximada, em linha reta.</small></div><div class="col-md-6"><label for="sort" class="form-label">Prioridade</label><select id="sort" v-model="sort" class="form-select"><option value="earliest">Primeiro horário disponível</option><option v-if="mode === 'in_person'" value="distance">Mais perto</option></select><label class="d-block mt-3"><input v-model="myTeam" type="checkbox" class="form-check-input me-2">Preferir minha equipe APS (mostrar somente ela)</label></div></div><div class="mt-3"><button class="btn btn-success" :disabled="busy || current?.status !== 'active'">Buscar atendimento</button><p v-if="current?.status !== 'active'" class="small text-secondary mt-2">Aguarde a validação do vínculo pela gestão.</p></div></form>
<section v-if="searched" class="mb-4"><h2 class="h4">Horários disponíveis</h2><p v-if="!slots.length && !busy">Nenhum horário encontrado para os filtros e serviços contratados.</p><label v-if="slots.length" class="alert alert-light border d-block"><input v-model="authorized" type="checkbox" class="form-check-input me-2">Ao confirmar o agendamento, autorizo o vínculo assistencial com a equipe escolhida para este acompanhamento.</label><div class="row g-3"><div v-for="s in slots" :key="s.id" class="col-md-6 col-xl-4"><article class="card card-body h-100"><span class="badge text-bg-light align-self-start mb-3">{{ s.modality === 'telehealth' ? 'Teleconsulta' : 'Presencial' }}</span><h3 class="h5">{{ s.professional_name }}</h3><p class="small text-secondary">{{ s.role === 'doctor' ? 'Médico' : 'Enfermeiro' }} · {{ s.service_unit }}</p><p>{{ s.starts_at }}<br><small>{{ s.address }}</small></p><p v-if="s.modality === 'in_person'" class="small">{{ s.distance_km === null ? 'Distância indisponível' : `${s.distance_km} km aproximados` }}</p><button class="btn btn-success mt-auto" :disabled="busy || !authorized" @click="book(s)">Confirmar agendamento</button></article></div></div></section>
<section class="card card-body"><h2 class="h4">Meus atendimentos e retornos</h2><p v-if="!appointments.length">Nenhum atendimento agendado.</p><div v-for="a in appointments" :key="a.id" class="border-bottom py-3"><strong>{{ a.patient_name }} · {{ a.professional_name }}</strong><p class="mb-2">{{ a.scheduled_at }} · {{ a.modality === 'telehealth' ? 'Teleconsulta' : 'Presencial' }} · {{ label(a.status) }}<br><small>{{ a.service_unit }} {{ a.address }}</small></p><button v-if="['expected', 'confirmed'].includes(a.status)" class="btn btn-sm btn-outline-secondary me-2" @click="supportId = a.id">Preciso de apoio</button><button v-if="a.status === 'expected'" class="btn btn-sm btn-outline-success" :disabled="busy" @click="confirm(a)">Confirmar retorno</button><button v-if="a.modality === 'telehealth' && ['confirmed', 'expected'].includes(a.status)" class="btn btn-sm btn-outline-success" @click="access(a)">Consultar acesso à teleconsulta</button><a v-if="links[a.id]" :href="links[a.id]" target="_blank" rel="noopener noreferrer" class="btn btn-sm btn-success ms-2">Entrar na sala</a></div><p class="small text-secondary mt-3">O link da teleconsulta é fornecido pelo profissional e liberado próximo ao horário. Para reagendar ou pedir apoio, procure o navegador de cuidado.</p></section>
<section v-if="supportId" class="card card-body mt-4"><h2 class="h5">Apoio para o retorno</h2><FormPanel :key="supportId" :fields="supportFields" :busy="busy" submit-label="Pedir acolhimento" @submit="support" /><button class="btn btn-link align-self-start mt-2" @click="supportId = null">Cancelar</button></section><section v-if="current?.kind === 'worker' && Number(current.user_id) === Number(auth.user.id) && current.status === 'active'" class="card card-body mt-4"><h2 class="h5">Convidar dependente adulto</h2><p class="small text-secondary">O dependente terá conta e histórico próprios. A cobertura e o vínculo serão validados. Para menores, procure a gestão para verificar a representação.</p><form class="row g-3" @submit.prevent="inviteDependent"><div class="col-md-8"><label for="dependent-email" class="form-label">E-mail do dependente</label><input id="dependent-email" v-model="email" class="form-control" type="email" required></div><div class="col-md-4 d-flex align-items-end"><button class="btn btn-outline-success" :disabled="busy">Gerar convite</button></div></form><input v-if="invitation" :value="invitation" class="form-control mt-3" readonly aria-label="Convite individual do dependente" @focus="$event.target.select()"></section>
</template>
